  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);

  const handleOptionChange = (questionId, option) => {
    setSelections((prev) => {
      const current = prev[questionId] || [];
      if (current.includes(option)) {
        return { ...prev, [questionId]: current.filter((o) => o !== option) };
      } else {
        return { ...prev, [questionId]: [...current, option] };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let totalScore = 0;
    questionsData.forEach((q) => {
      const userAns = selections[q.id] || [];
      const correctAns = q.answers;

      // Simple scoring: check if selection matches answers exactly
      const isCorrect = userAns.length === correctAns.length && 
                        userAns.every(val => correctAns.includes(val));

      if (isCorrect) totalScore++;
    });
    setScore(totalScore);
    setSubmitted(true);
  };

  return (
    <div className="quiz-container">
      <h1>CS Language Quiz</h1>
      <p className="subtitle">Test your knowledge of computer languages</p>

      {!submitted ? (
        <form onSubmit={handleSubmit}>
          {questionsData.map((q) => (
            <Question
              key={q.id}
              data={q}
              selectedOptions={selections[q.id] || []}
              onOptionChange={(option) => handleOptionChange(q.id, option)}
            />
          ))}
          <button type="submit" className="submit-btn">Submit Answers</button>
        </form>
      ) : (
        <div className="results">
          <h2>Quiz Completed!</h2>
          <p>Your score: {score} / {questionsData.length}</p>
          <button 
            className="submit-btn" 
            onClick={() => { setSubmitted(false); setSelections({}); }}
          >
            Try Again
          </button>
        </div>
      )}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
